package node

import (
	"github.com/google/uuid"

	"github.com/Gwakko/tenant-backoffice/backend/internal/domain/apperr"
)

// ID identifies a node. New values are generated by an application port.
type ID uuid.UUID

// ParseID parses the canonical textual form of a node ID.
func ParseID(s string) (ID, error) {
	u, err := uuid.Parse(s)
	if err != nil {
		return ID{}, apperr.New(apperr.InvalidID, "node id is not a valid UUID")
	}
	return ID(u), nil
}

// String returns the canonical textual form.
func (id ID) String() string { return uuid.UUID(id).String() }

// IsZero reports whether id is the zero value.
func (id ID) IsZero() bool { return id == ID{} }

// Path is the list of node IDs from the root down to the node itself.
type Path []ID

// Contains reports whether id is on the path.
func (p Path) Contains(id ID) bool {
	for _, x := range p {
		if x == id {
			return true
		}
	}
	return false
}

// Append returns a new path extended by id; p is not modified.
func (p Path) Append(id ID) Path {
	out := make(Path, len(p)+1)
	copy(out, p)
	out[len(p)] = id
	return out
}

// Parent returns the path without its last element, or nil for a root path.
func (p Path) Parent() Path {
	if len(p) <= 1 {
		return nil
	}
	out := make(Path, len(p)-1)
	copy(out, p)
	return out
}
